<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html;

use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepInput;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Forms\AuthorizationForm;
use Psr\Http\Message\ResponseInterface;

final class OidcStepRouter
{
    /** @var AuthorizationForm[] */
    private array $forms;

    public function __construct(array $forms, private readonly string $fallbackStep = '')
    {
        $this->forms = $forms;
    }

    public function resolve(?string $step, ?AuthenticationResult $error): ?AuthorizationForm
    {
        $step = $step ?? '';

        if ($step !== '') {
            foreach ($this->forms as $form) {
                if ($form->step() === $step) {
                    return $form;
                }
            }
        }

        foreach ($this->forms as $form) {
            if ($form->handle($error)) {
                return $form;
            }
        }

        if ($this->fallbackStep !== '') {
            foreach ($this->forms as $form) {
                if ($form->step() === $this->fallbackStep) {
                    return $form;
                }
            }
        }

        return null;
    }

    public function run(StepInput $input, ResponseInterface $response, ?AuthenticationResult $error, ?string $step, ?string $csid): ?StepResult
    {
        $form = $this->resolve($step, $error);
        if (!$form) {
            return null;
        }

        $legacyChallenges = $input->challenges->toLegacy();
        $base = rtrim($input->context->baseUrl, '/') . '/oauth';

        if ($csid !== null) {
            $auth = $form->autenticate(
                $input->authRequest,
                $input->context->tenant,
                $input->context->issuer,
                $csid,
                $input->context->state,
                $input->context->nonce,
                $legacyChallenges,
                $input->body ?? []
            );
            return StepResult::proceed($auth);
        }

        $response = $form->paint(
            $error,
            $input->context->locale,
            $base,
            $input->context->tenant,
            $legacyChallenges,
            $input->body ?? [],
            $input->request,
            $response
        );

        return StepResult::render($response);
    }
}
